#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int maxRemovals(std::string source, std::string pattern, std::vector<int>& targetIndices) {
        int n = source.size(), m = pattern.size();
        std::vector<int> is_target(n, 0);
        for (int idx : targetIndices) is_target[idx] = 1;

        const int INF = 1e9;
        std::vector<int> dp(m + 1, -INF);
        dp[0] = 0;

        for (int i = 0; i < n; ++i) {
            int cost = is_target[i];
            char ch = source[i];
            for (int j = m; j >= 1; --j) {
                if (ch == pattern[j - 1]) {
                    dp[j] = std::max(dp[j] + cost, dp[j - 1]);
                } else {
                    dp[j] = dp[j] + cost;
                }
            }
            dp[0] += cost;
        }
        return dp[m];
    }
};

import java.util.*;

class Solution {
    public int maxRemovals(String source, String pattern, int[] targetIndices) {
        int n = source.length(), m = pattern.length();
        int[] isTarget = new int[n];
        for (int idx : targetIndices) isTarget[idx] = 1;

        int INF = (int) 1e9;
        int[] dp = new int[m + 1];
        Arrays.fill(dp, -INF);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            int cost = isTarget[i];
            char ch = source.charAt(i);
            for (int j = m; j >= 1; j--) {
                if (ch == pattern.charAt(j - 1)) {
                    dp[j] = Math.max(dp[j] + cost, dp[j - 1]);
                } else {
                    dp[j] = dp[j] + cost;
                }
            }
            dp[0] += cost;
        }
        return dp[m];
    }
}

